function meta(el){var l=norm(labelOf(el)+' '+el.id+' '+el.name+' '+Object.keys(el.dataset||{}).map(function(k){return el.dataset[k]}).join(' ')),kind='';Object.keys(ALIAS).some(function(k){var a=ALIAS[k].split(' ');if(a.some(function(x){return x.length>1&&l.indexOf(norm(x))>=0})){kind=k;return true}});return{el:el,label:labelOf(el),key:l,kind:kind,type:el.type}}
