d.querySelector('#sep-ocr-mode').value=S.ocrMode;d.querySelector('#sep-ocr-lang').value=S.ocrLang;d.querySelector('#sep-ocr-mode').onchange=function(){S.ocrMode=this.value};d.querySelector('#sep-ocr-lang').onchange=function(){S.ocrLang=this.value};
function files(e){loadImages(Array.prototype.slice.call(e.target.files||[]),d)}d.querySelector('#sep-ocr-files').onchange=files;d.querySelector('#sep-camera-file').onchange=files;
d.querySelectorAll('[data-rot]').forEach(function(b){b.onclick=function(){if(!S.images.length)return;S.images[S.imageIndex].rot=(S.images[S.imageIndex].rot+Number(b.dataset.rot)+360)%360;analyzeQuality(S.images[S.imageIndex]);renderImage(d)}});
d.querySelector('#sep-filter').onchange=function(e){if(S.images.length){S.images[S.imageIndex].filter=e.target.value;renderImage(d)}};d.querySelector('#sep-deskew').onclick=function(){var x=S.images[S.imageIndex];if(!x)return;var a=estimateDeskew(drawCanvas(x,true,{max:900,ignoreCrop:true}));x.deskew=Math.abs(a)<.45?0:a;analyzeQuality(x);renderImage(d)};
var cropMode=false,start=null,c=d.querySelector('#sep-canvas'),help=d.querySelector('#sep-crop-help');d.querySelector('#sep-crop').onclick=function(){cropMode=!cropMode;this.classList.toggle('active',cropMode);help.textContent=cropMode?T('Drag over the exact text region. Recognition will process only that region.','اسحب فوق منطقة النص المطلوبة. سيحلل OCR هذا الجزء فقط.'):''};d.querySelector('#sep-crop-reset').onclick=function(){var x=S.images[S.imageIndex];if(x){x.crop=null;cropMode=false;help.textContent='';renderImage(d)}};function cp(e){var r=c.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}c.addEventListener('pointerdown',function(e){if(!cropMode)return;start=cp(e);try{c.setPointerCapture(e.pointerId)}catch(z){}e.preventDefault()});c.addEventListener('pointerup',function(e){if(!cropMode||!start)return;var p=cp(e),x=S.images[S.imageIndex],rx=Math.min(start.x,p.x),ry=Math.min(start.y,p.y),rw=Math.abs(p.x-start.x),rh=Math.abs(p.y-start.y);if(rw>.03&&rh>.03)x.crop={x:rx,y:ry,w:rw,h:rh};start=null;cropMode=false;help.textContent='';d.querySelector('#sep-crop').classList.remove('active');renderImage(d);e.preventDefault()});
