d.querySelector('#sep-build-review').onclick=function(){syncEditedText(d);buildOcrReview(d);go('review')};d.querySelector('#sep-select-all').onclick=function(){d.querySelectorAll('#sep-field-review input[type=checkbox]').forEach(function(x){x.checked=true})};d.querySelector('#sep-select-none').onclick=function(){d.querySelectorAll('#sep-field-review input[type=checkbox]').forEach(function(x){x.checked=false})};d.querySelector('#sep-select-safe').onclick=function(){d.querySelectorAll('#sep-field-review tr').forEach(function(tr){var x=tr.querySelector('input');if(x)x.checked=tr.dataset.safe==='1'})};d.querySelector('#sep-copy-text').onclick=function(){syncEditedText(d);var t=S.images.map(function(x){return x.text||''}).join('\n\n');navigator.clipboard&&navigator.clipboard.writeText(t);toast(T('Recognized text copied.','تم نسخ النص المتعرف عليه.'))};d.querySelector('#sep-apply').onclick=function(){applyOCR(d)};
