function imageFile(f,name){return new Promise(function(res,rej){var r=new FileReader();r.onerror=rej;r.onload=function(){var im=new Image();im.onerror=rej;im.onload=function(){res({name:name||f.name,url:r.result,img:im,rot:0,deskew:0,crop:null,filter:'document',text:'',confidence:0,quality:null,uncertain:[]})};im.src=r.result};r.readAsDataURL(f)})}
async function pdfImages(f){var pdfjs=await import('./pdfjs-local.mjs');pdfjs.GlobalWorkerOptions.workerSrc='./pdfjs-worker-local.mjs';var pdf=await pdfjs.getDocument({data:await f.arrayBuffer()}).promise,out=[];for(var n=1;n<=pdf.numPages;n++){var pg=await pdf.getPage(n),base=pg.getViewport({scale:1}),scale=Math.min(2.2,1800/Math.max(base.width,base.height)),vp=pg.getViewport({scale:scale}),c=D.createElement('canvas');c.width=Math.ceil(vp.width);c.height=Math.ceil(vp.height);await pg.render({canvasContext:c.getContext('2d',{willReadFrequently:true}),viewport:vp}).promise;var blob=await new Promise(function(r){c.toBlob(r,'image/png')});out.push(await imageFile(blob,f.name+' · '+T('page ','صفحة ')+n))}return out}
